const express = require('express');
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');

const app = express();

// Document storage configuration
const DOCS_ROOT = path.resolve('/var/app/documents');
const ALLOWED_EXTENSIONS = ['.pdf', '.txt', '.md', '.json', '.xml'];

// Rate limiting state
const rateLimits = new Map();

function checkRateLimit(ip) {
  const now = Date.now();
  const record = rateLimits.get(ip) || { count: 0, resetAt: now + 60000 };
  if (now > record.resetAt) {
    record.count = 0;
    record.resetAt = now + 60000;
  }
  record.count++;
  rateLimits.set(ip, record);
  return record.count <= 100;
}

// Validate that a filename is safe
function isValidFilename(filename) {
  // Block null bytes
  if (filename.includes('\x00')) return false;
  // Block obvious traversal
  if (filename.includes('..')) return false;
  // Must have allowed extension
  const ext = path.extname(filename).toLowerCase();
  if (!ALLOWED_EXTENSIONS.includes(ext)) return false;
  // Block absolute paths
  if (path.isAbsolute(filename)) return false;
  // Block backslashes
  if (filename.includes('\\')) return false;
  return true;
}

// Resolve document path safely
function resolveDocPath(category, filename) {
  // Validate filename first
  if (!isValidFilename(filename)) {
    return null;
  }
  // Validate category (alphanumeric + hyphens only)
  if (!/^[a-zA-Z0-9\-]+$/.test(category)) {
    return null;
  }
  // Build the path
  const resolved = path.join(DOCS_ROOT, category, filename);
  return resolved;
}

// Normalize unicode in path components for consistent storage
function normalizePath(filepath) {
  // NFC normalization for consistent unicode handling
  return filepath.normalize('NFC');
}

// Security check: ensure resolved path is within DOCS_ROOT
function isWithinRoot(resolvedPath) {
  const normalizedRoot = DOCS_ROOT.normalize('NFC');
  const normalizedPath = resolvedPath.normalize('NFC');
  return normalizedPath.startsWith(normalizedRoot + path.sep);
}

app.get('/api/documents/:category/:filename', (req, res) => {
  if (!checkRateLimit(req.ip)) {
    return res.status(429).json({ error: 'Rate limited' });
  }

  const { category, filename } = req.params;

  // Decode URI components
  let decodedFilename;
  try {
    decodedFilename = decodeURIComponent(filename);
  } catch (e) {
    return res.status(400).json({ error: 'Invalid filename encoding' });
  }

  // Resolve the document path (includes validation)
  const docPath = resolveDocPath(category, decodedFilename);
  if (!docPath) {
    return res.status(400).json({ error: 'Invalid document path' });
  }

  // Security boundary check
  if (!isWithinRoot(docPath)) {
    return res.status(403).json({ error: 'Access denied' });
  }

  // Normalize for filesystem access
  const finalPath = normalizePath(docPath);

  // Read and serve the file
  fs.readFile(finalPath, (err, data) => {
    if (err) {
      if (err.code === 'ENOENT') {
        return res.status(404).json({ error: 'Document not found' });
      }
      return res.status(500).json({ error: 'Internal error' });
    }

    const ext = path.extname(finalPath).toLowerCase();
    const contentTypes = {
      '.pdf': 'application/pdf',
      '.txt': 'text/plain',
      '.md': 'text/markdown',
      '.json': 'application/json',
      '.xml': 'application/xml'
    };

    res.setHeader('Content-Type', contentTypes[ext] || 'application/octet-stream');
    res.setHeader('X-Content-Hash', crypto.createHash('sha256').update(data).digest('hex'));
    res.send(data);
  });
});

app.post('/api/documents/:category/:filename', express.raw({ limit: '5mb' }), (req, res) => {
  if (!checkRateLimit(req.ip)) {
    return res.status(429).json({ error: 'Rate limited' });
  }

  const { category, filename } = req.params;

  let decodedFilename;
  try {
    decodedFilename = decodeURIComponent(filename);
  } catch (e) {
    return res.status(400).json({ error: 'Invalid filename encoding' });
  }

  const docPath = resolveDocPath(category, decodedFilename);
  if (!docPath) {
    return res.status(400).json({ error: 'Invalid document path' });
  }

  if (!isWithinRoot(docPath)) {
    return res.status(403).json({ error: 'Access denied' });
  }

  const finalPath = normalizePath(docPath);

  // Ensure directory exists
  const dir = path.dirname(finalPath);
  fs.mkdirSync(dir, { recursive: true });

  fs.writeFile(finalPath, req.body, (err) => {
    if (err) {
      return res.status(500).json({ error: 'Write failed' });
    }
    res.json({ success: true, path: `${category}/${decodedFilename}` });
  });
});

app.listen(3000);
module.exports = app;
